export interface Movie {
  id: number;
  title: string;
  genre: string;
  runtimeMinutes: number;
  format: 'PL dubbing' | 'PL subtitles';
}

export interface Screening {
  id: number;
  movieId: number;
  date: string;
  time: string;
  occupiedSeats: string[];
}

export interface ReservationCustomer {
  firstName: string;
  lastName: string;
  email: string;
  phone: string;
}

export interface Reservation {
  id: number;
  screeningId: number;
  seats: string[];
  customer: ReservationCustomer;
  totalPrice: number;
}

import { Movie, Reservation, ReservationCustomer, Screening } from './types';

const BASE_URL = 'http://localhost:3000';

async function getJson<T>(path: string): Promise<T> {
  const response = await fetch(`${BASE_URL}${path}`);
  if (!response.ok) {
    throw new Error(`Request to ${path} failed with status ${response.status}`);
  }
  return response.json() as Promise<T>;
}

export function fetchMovies(): Promise<Movie[]> {
  return getJson<Movie[]>('/movies');
}

export function fetchMovie(id: number): Promise<Movie> {
  return getJson<Movie>(`/movies/${id}`);
}

export function fetchScreeningsByDate(date: string): Promise<Screening[]> {
  return getJson<Screening[]>(`/screenings?date=${encodeURIComponent(date)}`);
}

export function fetchScreening(id: number): Promise<Screening> {
  return getJson<Screening>(`/screenings/${id}`);
}

export interface CreateReservationPayload {
  screeningId: number;
  seats: string[];
  customer: ReservationCustomer;
  totalPrice: number;
}

export async function createReservation(
  payload: CreateReservationPayload,
): Promise<Reservation> {
  const response = await fetch(`${BASE_URL}/reservations`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(payload),
  });
  if (!response.ok) {
    throw new Error(`Reservation request failed with status ${response.status}`);
  }
  return response.json() as Promise<Reservation>;
}

import dayjs from 'dayjs';

export const ISO_FORMAT = 'YYYY-MM-DD';
const ISO_DATE_RE = /^\d{4}-\d{2}-\d{2}$/;

export function todayISO(): string {
  return dayjs().format(ISO_FORMAT);
}

export function isValidIsoDate(value: string): boolean {
  if (!ISO_DATE_RE.test(value)) return false;
  const parsed = dayjs(value);
  return parsed.isValid() && parsed.format(ISO_FORMAT) === value;
}

export function isPastDate(iso: string): boolean {
  return iso < todayISO();
}

export function resolveSelectedDate(raw: string | null): string {
  if (raw && isValidIsoDate(raw) && !isPastDate(raw)) {
    return raw;
  }
  return todayISO();
}

export function addDays(iso: string, days: number): string {
  return dayjs(iso).add(days, 'day').format(ISO_FORMAT);
}

export function weekdayFull(iso: string): string {
  return dayjs(iso).format('dddd');
}

export function formatShowDate(date: string, time: string): string {
  return `${dayjs(date).format('dddd D MMM')} ${time}`;
}

export const ROW_COUNT = 15;
export const ACCESSIBLE_ROW = 1;
export const ACCESSIBLE_COLUMNS = [10, 11, 12, 13, 14, 15];
export const COUCH_ROW = 15;
export const COUCH_PRICE = 89;
export const MAX_SEATS_PER_BOOKING = 10;

export type SeatState = 'available' | 'selected' | 'unavailable' | 'accessible';

export const SEAT_COLORS: Record<SeatState, string> = {
  available: '#2E7D32',
  selected: '#F9A825',
  unavailable: '#C62828',
  accessible: '#1565C0',
};

export function seatId(row: number, column: number): string {
  return `R${row}C${column}`;
}

export function parseSeatId(id: string): { row: number; column: number } {
  const match = /^R(\d+)C(\d+)$/.exec(id);
  if (!match) {
    throw new Error(`Invalid seat id: ${id}`);
  }
  return { row: Number(match[1]), column: Number(match[2]) };
}

export function isAccessible(row: number, column: number): boolean {
  return row === ACCESSIBLE_ROW && ACCESSIBLE_COLUMNS.includes(column);
}

export function priceForRow(row: number): number {
  if (row <= 5) return 25;
  if (row <= 10) return 32;
  return 39;
}

export function blockColumns(row: number): { a: number[]; b: number[]; c: number[] } {
  const a = row > 10 ? [1, 2, 3, 4] : [];
  const b = Array.from({ length: 16 }, (_, i) => i + 5);
  const c = [21, 22, 23, 24];
  return { a, b, c };
}

export function couchPairForColumn(column: number): [number, number] {
  const start = column % 2 === 0 ? column - 1 : column;
  return [start, start + 1];
}

export type Cell =
  | { kind: 'seat'; column: number }
  | { kind: 'couch'; columns: [number, number] };

export function toCells(columns: number[], isCouchRow: boolean): Cell[] {
  if (!isCouchRow) {
    return columns.map((column) => ({ kind: 'seat', column }));
  }
  const cells: Cell[] = [];
  for (let i = 0; i < columns.length; i += 2) {
    cells.push({ kind: 'couch', columns: [columns[i], columns[i + 1]] });
  }
  return cells;
}

export function gridColumn(column: number): number {
  if (column <= 4) return column + 1;
  if (column <= 20) return column + 2;
  return column + 3;
}

export const LEFT_LABEL_COLUMN = 1;
export const AISLE_1_COLUMN = 6;
export const AISLE_2_COLUMN = 23;
export const RIGHT_LABEL_COLUMN = 28;

export function seatState(row: number, column: number, occupied: boolean, selected: boolean): SeatState {
  if (occupied) return 'unavailable';
  if (selected) return 'selected';
  if (isAccessible(row, column)) return 'accessible';
  return 'available';
}

export function couchState(occupiedA: boolean, occupiedB: boolean, selected: boolean): SeatState {
  if (occupiedA || occupiedB) return 'unavailable';
  if (selected) return 'selected';
  return 'available';
}

import { COUCH_PRICE, COUCH_ROW, couchPairForColumn, parseSeatId, priceForRow, seatId } from './seatLayout';

export interface Ticket {
  row: number;
  kind: 'seat' | 'couch';
  columns: number[];
  price: number;
}

export function buildTickets(seatIds: string[]): Ticket[] {
  const parsed = seatIds.map((id) => ({ id, ...parseSeatId(id) }));
  const consumed = new Set<string>();
  const sorted = [...parsed].sort((a, b) => a.row - b.row || a.column - b.column);
  const tickets: Ticket[] = [];

  for (const entry of sorted) {
    if (consumed.has(entry.id)) continue;
    if (entry.row === COUCH_ROW) {
      const pair = couchPairForColumn(entry.column);
      consumed.add(seatId(COUCH_ROW, pair[0]));
      consumed.add(seatId(COUCH_ROW, pair[1]));
      tickets.push({ row: COUCH_ROW, kind: 'couch', columns: pair, price: COUCH_PRICE });
    } else {
      consumed.add(entry.id);
      tickets.push({ row: entry.row, kind: 'seat', columns: [entry.column], price: priceForRow(entry.row) });
    }
  }

  tickets.sort((a, b) => a.row - b.row || a.columns[0] - b.columns[0]);
  return tickets;
}

export function ticketSeatIds(ticket: Ticket): string[] {
  return ticket.columns.map((column) => seatId(ticket.row, column));
}

export function orderedSeatIds(seatIds: string[]): string[] {
  return buildTickets(seatIds).flatMap(ticketSeatIds);
}

export function totalPrice(seatIds: string[]): number {
  return buildTickets(seatIds).reduce((sum, ticket) => sum + ticket.price, 0);
}

export function formatPrice(amount: number): string {
  return `${amount.toFixed(2)} PLN`;
}

import { useSyncExternalStore } from 'react';

const STORAGE_KEY = 'cinescope.booking';

export interface BookingFormValues {
  firstName: string;
  lastName: string;
  email: string;
  confirmEmail: string;
  phone: string;
  termsAccepted: boolean;
}

export interface BookingState {
  screeningId: number;
  seats: string[];
  form: BookingFormValues;
  paid: boolean;
  paidEmail: string | null;
}

function emptyForm(): BookingFormValues {
  return {
    firstName: '',
    lastName: '',
    email: '',
    confirmEmail: '',
    phone: '',
    termsAccepted: false,
  };
}

export function emptyBooking(screeningId: number): BookingState {
  return { screeningId, seats: [], form: emptyForm(), paid: false, paidEmail: null };
}

function readStorage(): BookingState | null {
  try {
    const raw = sessionStorage.getItem(STORAGE_KEY);
    if (!raw) return null;
    return JSON.parse(raw) as BookingState;
  } catch {
    return null;
  }
}

let booking: BookingState | null = readStorage();
const listeners = new Set<() => void>();

function notify(): void {
  listeners.forEach((listener) => listener());
}

function subscribe(listener: () => void): () => void {
  listeners.add(listener);
  return () => listeners.delete(listener);
}

export function getBookingSnapshot(): BookingState | null {
  return booking;
}

export function setBooking(next: BookingState | null): void {
  booking = next;
  if (next) {
    sessionStorage.setItem(STORAGE_KEY, JSON.stringify(next));
  } else {
    sessionStorage.removeItem(STORAGE_KEY);
  }
  notify();
}

export function clearBooking(): void {
  setBooking(null);
}

export function ensureBookingForScreening(screeningId: number): BookingState {
  if (booking && booking.screeningId === screeningId && !booking.paid) {
    return booking;
  }
  const fresh = emptyBooking(screeningId);
  setBooking(fresh);
  return fresh;
}

export function useBooking(): BookingState | null {
  return useSyncExternalStore(subscribe, getBookingSnapshot, getBookingSnapshot);
}

import { BookingFormValues } from './bookingStore';

export interface FormErrors {
  firstName?: string;
  lastName?: string;
  email?: string;
  confirmEmail?: string;
  phone?: string;
  termsAccepted?: string;
}

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const PHONE_RE = /^\d{9}$/;

export function validateForm(form: BookingFormValues): FormErrors {
  const errors: FormErrors = {};

  if (form.firstName.length === 0) {
    errors.firstName = 'First name is required';
  } else if (form.firstName.length < 2) {
    errors.firstName = 'First name must be at least 2 characters';
  }

  if (form.lastName.length === 0) {
    errors.lastName = 'Last name is required';
  } else if (form.lastName.length < 2) {
    errors.lastName = 'Last name must be at least 2 characters';
  }

  if (form.email.length === 0) {
    errors.email = 'Email is required';
  } else if (!EMAIL_RE.test(form.email)) {
    errors.email = 'Enter a valid email address';
  }

  if (form.confirmEmail.length === 0) {
    errors.confirmEmail = 'Confirm email is required';
  } else if (form.confirmEmail !== form.email) {
    errors.confirmEmail = 'Email addresses do not match';
  }

  if (form.phone.length > 0 && !PHONE_RE.test(form.phone)) {
    errors.phone = 'Phone number must be exactly 9 digits';
  }

  if (!form.termsAccepted) {
    errors.termsAccepted = 'You must accept the terms and conditions';
  }

  return errors;
}

import Snackbar from '@mui/material/Snackbar';
import { createContext, ReactNode, useCallback, useContext, useState } from 'react';

interface ToastContextValue {
  showToast: (message: string) => void;
}

const ToastContext = createContext<ToastContextValue | null>(null);

export function ToastProvider({ children }: { children: ReactNode }) {
  const [message, setMessage] = useState<string | null>(null);
  const [toastKey, setToastKey] = useState(0);

  const showToast = useCallback((next: string) => {
    setMessage(next);
    setToastKey((key) => key + 1);
  }, []);

  const handleClose = useCallback((_event: unknown, reason?: string) => {
    if (reason === 'clickaway') return;
    setMessage(null);
  }, []);

  return (
    <ToastContext.Provider value={{ showToast }}>
      {children}
      <Snackbar
        key={toastKey}
        open={message !== null}
        autoHideDuration={4000}
        onClose={handleClose}
        message={<span data-testid="toast">{message}</span>}
      />
    </ToastContext.Provider>
  );
}

export function useToast(): ToastContextValue {
  const context = useContext(ToastContext);
  if (!context) {
    throw new Error('useToast must be used within a ToastProvider');
  }
  return context;
}

import Button from '@mui/material/Button';
import { DatePicker } from '@mui/x-date-pickers/DatePicker';
import dayjs, { Dayjs } from 'dayjs';
import { useCallback, useEffect, useState } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import { fetchMovies, fetchScreeningsByDate } from '../lib/api';
import { addDays, resolveSelectedDate, todayISO, weekdayFull } from '../lib/dateUtils';
import { Movie, Screening } from '../lib/types';

interface LoadState {
  status: 'loading' | 'error' | 'loaded';
  movies: Movie[];
  screenings: Screening[];
}

interface MovieCard {
  movie: Movie;
  screenings: Screening[];
}

function buildDayButtons(): { iso: string; label: string }[] {
  const today = todayISO();
  const days = [{ iso: today, label: 'Today' }];
  for (let i = 1; i <= 4; i += 1) {
    const iso = addDays(today, i);
    days.push({ iso, label: weekdayFull(iso) });
  }
  return days;
}

export function MovieListPage() {
  const [searchParams, setSearchParams] = useSearchParams();
  const navigate = useNavigate();
  const rawDate = searchParams.get('date');
  const selectedDate = resolveSelectedDate(rawDate);
  const dayButtons = buildDayButtons();

  const [state, setState] = useState<LoadState>({ status: 'loading', movies: [], screenings: [] });

  const load = useCallback(() => {
    setState((prev) => ({ ...prev, status: 'loading' }));
    Promise.all([fetchMovies(), fetchScreeningsByDate(selectedDate)])
      .then(([movies, screenings]) => setState({ status: 'loaded', movies, screenings }))
      .catch(() => setState({ status: 'error', movies: [], screenings: [] }));
  }, [selectedDate]);

  useEffect(() => {
    load();
  }, [load]);

  function selectDate(iso: string) {
    setSearchParams({ date: iso });
  }

  function handleDatePickerChange(value: Dayjs | null) {
    if (value && value.isValid()) {
      selectDate(value.format('YYYY-MM-DD'));
    }
  }

  const cards: MovieCard[] = [];
  if (state.status === 'loaded') {
    const screeningsByMovie = new Map<number, Screening[]>();
    for (const screening of state.screenings) {
      const list = screeningsByMovie.get(screening.movieId) ?? [];
      list.push(screening);
      screeningsByMovie.set(screening.movieId, list);
    }
    for (const movie of state.movies) {
      const screenings = screeningsByMovie.get(movie.id);
      if (screenings && screenings.length > 0) {
        cards.push({
          movie,
          screenings: [...screenings].sort((a, b) => a.time.localeCompare(b.time)),
        });
      }
    }
  }

  return (
    <div>
      <div data-testid="day-picker">
        {dayButtons.map((day) => (
          <Button
            key={day.iso}
            data-testid="day-button"
            data-date={day.iso}
            data-selected={day.iso === selectedDate}
            variant={day.iso === selectedDate ? 'contained' : 'outlined'}
            onClick={() => selectDate(day.iso)}
          >
            {day.label}
          </Button>
        ))}
        <DatePicker
          value={dayjs(selectedDate)}
          onChange={handleDatePickerChange}
          disablePast
          slotProps={{ textField: { 'data-testid': 'date-picker' } }}
        />
      </div>
      <div data-testid="movie-list">
        {state.status === 'loading' && <div data-testid="movies-loading">Loading…</div>}
        {state.status === 'error' && (
          <div>
            <div data-testid="movies-error">Failed to load movies</div>
            <Button data-testid="movies-retry-button" onClick={load}>
              Retry
            </Button>
          </div>
        )}
        {state.status === 'loaded' && cards.length === 0 && (
          <div data-testid="movies-empty">No screenings on this day</div>
        )}
        {state.status === 'loaded' &&
          cards.map(({ movie, screenings }) => (
            <div key={movie.id} data-testid="movie-card" data-movie-id={movie.id}>
              <div data-testid="movie-title">{movie.title}</div>
              <div data-testid="movie-genre">{movie.genre}</div>
              <div data-testid="movie-runtime">{movie.runtimeMinutes} min</div>
              <div data-testid="movie-format">{movie.format}</div>
              <div>
                {screenings.map((screening) => (
                  <Button
                    key={screening.id}
                    data-testid="screening-button"
                    data-screening-id={screening.id}
                    onClick={() => navigate(`/screenings/${screening.id}/seats`)}
                  >
                    {screening.time}
                  </Button>
                ))}
              </div>
            </div>
          ))}
      </div>
    </div>
  );
}

