import { useNavigate, useParams } from 'react-router-dom';
import { fetchMovie, fetchScreening } from '../lib/api';
import { clearBooking, ensureBookingForScreening, setBooking, useBooking } from '../lib/bookingStore';
import { formatShowDate } from '../lib/dateUtils';
import {
  AISLE_1_COLUMN,
  AISLE_2_COLUMN,
  Cell,
  LEFT_LABEL_COLUMN,
  MAX_SEATS_PER_BOOKING,
  RIGHT_LABEL_COLUMN,
  ROW_COUNT,
  SEAT_COLORS,
  SeatState,
  blockColumns,
  couchState,
  gridColumn,
  seatId,
  seatState,
  toCells,
} from '../lib/seatLayout';
import { buildTickets } from '../lib/ticketing';
import { useToast } from '../lib/toast';
import { Movie, Screening } from '../lib/types';
import styles from './SeatSelectionPage.module.scss';

interface LoadedData {
  status: 'loading' | 'loaded';
  screening?: Screening;
  movie?: Movie;
}

const LEGEND_ITEMS: { state: SeatState; label: string }[] = [
  { state: 'available', label: 'Available' },
  { state: 'selected', label: 'Selected' },
  { state: 'unavailable', label: 'Unavailable' },
  { state: 'accessible', label: 'Accessible' },
];

function SeatCell({
  row,
  cell,
  occupied,
  selected,
  onToggleSeat,
  onToggleCouch,
}: {
  row: number;
  cell: Cell;
  occupied: Set<string>;
  selected: Set<string>;
  onToggleSeat: (id: string) => void;
  onToggleCouch: (a: string, b: string) => void;
}) {
  if (cell.kind === 'seat') {
    const id = seatId(row, cell.column);
    const state = seatState(row, cell.column, occupied.has(id), selected.has(id));
    return (
      <button
        type="button"
        className={styles.seat}
        data-testid="seat"
        data-row={row}
        data-column={cell.column}
        data-state={state}
        style={{ gridColumn: gridColumn(cell.column), backgroundColor: SEAT_COLORS[state] }}
        disabled={state === 'unavailable'}
        onClick={() => onToggleSeat(id)}
      >
        {cell.column}
      </button>
    );
  }

  const [a, b] = cell.columns;
  const idA = seatId(row, a);
  const idB = seatId(row, b);
  const state = couchState(occupied.has(idA), occupied.has(idB), selected.has(idA) && selected.has(idB));
  return (
    <button
      type="button"
      className={styles.couch}
      data-testid="couch"
      data-row={row}
      data-column-start={a}
      data-column-end={b}
      data-state={state}
      style={{
        gridColumn: `${gridColumn(a)} / ${gridColumn(b) + 1}`,
        backgroundColor: SEAT_COLORS[state],
      }}
      disabled={state === 'unavailable'}
      onClick={() => onToggleCouch(idA, idB)}
    >
      {a}-{b}
    </button>
  );
}

function SeatRow({
  row,
  occupied,
  selected,
  onToggleSeat,
  onToggleCouch,
}: {
  row: number;
  occupied: Set<string>;
  selected: Set<string>;
  onToggleSeat: (id: string) => void;
  onToggleCouch: (a: string, b: string) => void;
}) {
  const isCouchRow = row === 15;
  const { a, b, c } = blockColumns(row);
  const cellsA = toCells(a, isCouchRow);
  const cellsB = toCells(b, isCouchRow);
  const cellsC = toCells(c, isCouchRow);

  const cellProps = { row, occupied, selected, onToggleSeat, onToggleCouch };

  return (
    <div className={styles.row} data-testid="seat-row" data-row={row}>
      <div
        className={styles.label}
        data-testid="row-label-left"
        data-row={row}
        style={{ gridColumn: LEFT_LABEL_COLUMN }}
      >
        {row}
      </div>
      {cellsA.map((cell) => (
        <SeatCell key={`a-${cell.kind === 'seat' ? cell.column : cell.columns.join('-')}`} cell={cell} {...cellProps} />
      ))}
      <div data-testid="aisle" data-row={row} style={{ gridColumn: AISLE_1_COLUMN }} />
      {cellsB.map((cell) => (
        <SeatCell key={`b-${cell.kind === 'seat' ? cell.column : cell.columns.join('-')}`} cell={cell} {...cellProps} />
      ))}
      <div data-testid="aisle" data-row={row} style={{ gridColumn: AISLE_2_COLUMN }} />
      {cellsC.map((cell) => (
        <SeatCell key={`c-${cell.kind === 'seat' ? cell.column : cell.columns.join('-')}`} cell={cell} {...cellProps} />
      ))}
      <div
        className={styles.label}
        data-testid="row-label-right"
        data-row={row}
        style={{ gridColumn: RIGHT_LABEL_COLUMN }}
      >
        {row}
      </div>
    </div>
  );
}

function Legend() {
  return (
    <div className={styles.legend} data-testid="legend">
      {LEGEND_ITEMS.map((item) => (
        <div key={item.state} className={styles.legendItem} data-testid="legend-item" data-state={item.state}>
          <span className={styles.swatch} style={{ backgroundColor: SEAT_COLORS[item.state] }} />
          <span>{item.label}</span>
        </div>
      ))}
    </div>
  );
}

function SelectedSeatsPanel({ seatIds }: { seatIds: string[] }) {
  const tickets = buildTickets(seatIds);
  const rowMap = new Map<number, string[]>();
  for (const ticket of tickets) {
    const description = ticket.kind === 'couch' ? `${ticket.columns[0]}-${ticket.columns[1]}` : `${ticket.columns[0]}`;
    const list = rowMap.get(ticket.row) ?? [];
    list.push(description);
    rowMap.set(ticket.row, list);
  }
  const rows = [...rowMap.keys()].sort((x, y) => x - y);

  return (
    <div className={styles.selectedPanel} data-testid="selected-seats">
      <div data-testid="selected-seats-count">Selected seats: {seatIds.length}</div>
      {rows.map((row) => (
        <div key={row} data-testid="selected-seats-row" data-row={row}>
          Row {row}: {rowMap.get(row)?.join(', ')}
        </div>
      ))}
    </div>
  );
}

export function SeatSelectionPage() {
  const { id } = useParams();
  const screeningId = Number(id);
  const navigate = useNavigate();
  const { showToast } = useToast();
  const booking = useBooking();
  const [data, setData] = useState<LoadedData>({ status: 'loading' });

  useEffect(() => {
    let cancelled = false;
    fetchScreening(screeningId)
      .then((screening) => fetchMovie(screening.movieId).then((movie) => ({ screening, movie })))
      .then(({ screening, movie }) => {
        if (cancelled) return;
        ensureBookingForScreening(screeningId);
        setData({ status: 'loaded', screening, movie });
      })
      .catch(() => {
        if (!cancelled) navigate('/', { replace: true });
      });
    return () => {
      cancelled = true;
    };
  }, [screeningId, navigate]);

  if (data.status !== 'loaded' || !booking || booking.screeningId !== screeningId) {
    return null;
  }

  const screening = data.screening as Screening;
  const occupied = new Set(screening.occupiedSeats);
  const selected = new Set(booking.seats);

  function toggleSeat(targetId: string) {
    if (occupied.has(targetId)) return;
    const currentBooking = booking!;
    const already = currentBooking.seats.includes(targetId);
    let nextSeats: string[];
    if (already) {
      nextSeats = currentBooking.seats.filter((s) => s !== targetId);
    } else {
      if (currentBooking.seats.length + 1 > MAX_SEATS_PER_BOOKING) {
        showToast('Maximum 10 seats per booking');
        return;
      }
      nextSeats = [...currentBooking.seats, targetId];
    }
    setBooking({ ...currentBooking, seats: nextSeats });
  }

  function toggleCouch(idA: string, idB: string) {
    if (occupied.has(idA) || occupied.has(idB)) return;
    const currentBooking = booking!;
    const already = currentBooking.seats.includes(idA) && currentBooking.seats.includes(idB);
    let nextSeats: string[];
    if (already) {
      nextSeats = currentBooking.seats.filter((s) => s !== idA && s !== idB);
    } else {
      if (currentBooking.seats.length + 2 > MAX_SEATS_PER_BOOKING) {
        showToast('Maximum 10 seats per booking');
        return;
      }
      nextSeats = [...currentBooking.seats, idA, idB];
    }
    setBooking({ ...currentBooking, seats: nextSeats });
  }

  function handleCancel() {
    clearBooking();
    navigate('/');
  }

  function handleContinue() {
    if (booking!.seats.length === 0) return;
    navigate(`/screenings/${screeningId}/summary`);
  }

  const rows = Array.from({ length: ROW_COUNT }, (_, i) => i + 1);

  return (
    <div className={styles.page}>
      <h1 data-testid="seat-map-title">Choose your seats</h1>
      <div data-testid="seat-map-subtitle">Show Date: {formatShowDate(screening.date, screening.time)}</div>
      <div className={styles.limitInfo} data-testid="seat-limit-info">
        You can reserve up to 10 seats per reservation
      </div>
      <div className={styles.screen} data-testid="screen-indicator">
        SCREEN
      </div>
      <div className={styles.seatMap} data-testid="seat-map">
        {rows.map((row) => (
          <SeatRow
            key={row}
            row={row}
            occupied={occupied}
            selected={selected}
            onToggleSeat={toggleSeat}
            onToggleCouch={toggleCouch}
          />
        ))}
      </div>
      <Legend />
      <SelectedSeatsPanel seatIds={booking.seats} />
      <div className={styles.actions}>
        <Button data-testid="cancel-button" onClick={handleCancel}>
          Cancel
        </Button>
        <Button data-testid="continue-button" disabled={booking.seats.length === 0} onClick={handleContinue}>
          Continue
        </Button>
      </div>
    </div>
  );
}

export default SeatSelectionPage;

import Button from '@mui/material/Button';
import { useEffect, useState } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { fetchMovie, fetchScreening } from '../lib/api';
import { getBookingSnapshot, setBooking, useBooking } from '../lib/bookingStore';
import { buildTickets, formatPrice, Ticket, ticketSeatIds } from '../lib/ticketing';
import { Movie, Screening } from '../lib/types';

interface LoadedData {
  status: 'loading' | 'loaded';
  screening?: Screening;
  movie?: Movie;
}

export function SummaryPage() {
  const { id } = useParams();
  const screeningId = Number(id);
  const navigate = useNavigate();
  const booking = useBooking();
  const [data, setData] = useState<LoadedData>({ status: 'loading' });

  useEffect(() => {
    const snapshot = getBookingSnapshot();
    if (!snapshot || snapshot.paid || snapshot.screeningId !== screeningId || snapshot.seats.length === 0) {
      navigate('/', { replace: true });
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    let cancelled = false;
    fetchScreening(screeningId)
      .then((screening) => fetchMovie(screening.movieId).then((movie) => ({ screening, movie })))
      .then(({ screening, movie }) => {
        if (!cancelled) setData({ status: 'loaded', screening, movie });
      })
      .catch(() => {
        if (!cancelled) navigate('/', { replace: true });
      });
    return () => {
      cancelled = true;
    };
  }, [screeningId, navigate]);

  if (!booking || data.status !== 'loaded') {
    return null;
  }

  const screening = data.screening as Screening;
  const movie = data.movie as Movie;
  const tickets = buildTickets(booking.seats);
  const total = tickets.reduce((sum, ticket) => sum + ticket.price, 0);

  function handleRemove(ticket: Ticket) {
    const idsToRemove = new Set(ticketSeatIds(ticket));
    const nextSeats = booking!.seats.filter((s) => !idsToRemove.has(s));
    setBooking({ ...booking!, seats: nextSeats });
    if (nextSeats.length === 0) {
      navigate(`/screenings/${screeningId}/seats`);
    }
  }

  return (
    <div>
      <h1 data-testid="summary-title">Your tickets</h1>
      <div data-testid="summary-list">
        {tickets.map((ticket, index) => (
          <div data-testid="summary-item" key={index}>
            <span data-testid="summary-item-title">{movie.title}</span>
            <span data-testid="summary-item-datetime">
              {screening.date} {screening.time}
            </span>
            <span data-testid="summary-item-row">{ticket.row}</span>
            <span data-testid="summary-item-seat">
              {ticket.kind === 'couch' ? `Couch ${ticket.columns[0]}-${ticket.columns[1]}` : `${ticket.columns[0]}`}
            </span>
            <span data-testid="summary-item-price">{formatPrice(ticket.price)}</span>
            <Button data-testid="summary-item-remove-button" onClick={() => handleRemove(ticket)}>
              Remove
            </Button>
          </div>
        ))}
      </div>
      <div data-testid="summary-total">Total: {formatPrice(total)}</div>
      <div>
        <Button data-testid="back-button" onClick={() => navigate(`/screenings/${screeningId}/seats`)}>
          Back
        </Button>
        <Button data-testid="confirm-button" onClick={() => navigate(`/screenings/${screeningId}/checkout`)}>
          Confirm
        </Button>
      </div>
    </div>
  );
}

export default SummaryPage;

import Button from '@mui/material/Button';
import Checkbox from '@mui/material/Checkbox';
import FormControlLabel from '@mui/material/FormControlLabel';
import TextField from '@mui/material/TextField';
import { useEffect, useState } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { createReservation } from '../lib/api';
import { BookingFormValues, getBookingSnapshot, setBooking, useBooking } from '../lib/bookingStore';
import { formatPrice, orderedSeatIds, totalPrice } from '../lib/ticketing';
import { useToast } from '../lib/toast';
import { FormErrors, validateForm } from '../lib/validation';

type TextFieldName = 'firstName' | 'lastName' | 'email' | 'confirmEmail' | 'phone';
type FieldName = TextFieldName | 'termsAccepted';

const TEXT_FIELDS: { name: TextFieldName; label: string; testid: string; labelTestid: string; errorTestid: string }[] = [
  { name: 'firstName', label: 'First name *', testid: 'first-name-input', labelTestid: 'first-name-label', errorTestid: 'first-name-error' },
  { name: 'lastName', label: 'Last name *', testid: 'last-name-input', labelTestid: 'last-name-label', errorTestid: 'last-name-error' },
  { name: 'email', label: 'Email *', testid: 'email-input', labelTestid: 'email-label', errorTestid: 'email-error' },
  { name: 'confirmEmail', label: 'Confirm email *', testid: 'confirm-email-input', labelTestid: 'confirm-email-label', errorTestid: 'confirm-email-error' },
  { name: 'phone', label: 'Phone number', testid: 'phone-input', labelTestid: 'phone-label', errorTestid: 'phone-error' },
];

const ALL_TOUCHED: Record<FieldName, boolean> = {
  firstName: true,
  lastName: true,
  email: true,
  confirmEmail: true,
  phone: true,
  termsAccepted: true,
};

export function CheckoutPage() {
  const { id } = useParams();
  const screeningId = Number(id);
  const navigate = useNavigate();
  const { showToast } = useToast();
  const booking = useBooking();
  const [touched, setTouched] = useState<Record<FieldName, boolean>>({
    firstName: false,
    lastName: false,
    email: false,
    confirmEmail: false,
    phone: false,
    termsAccepted: false,
  });
  const [submitting, setSubmitting] = useState(false);

  useEffect(() => {
    const snapshot = getBookingSnapshot();
    if (!snapshot || snapshot.paid || snapshot.screeningId !== screeningId || snapshot.seats.length === 0) {
      navigate('/', { replace: true });
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  if (!booking) {
    return null;
  }

  const errors: FormErrors = validateForm(booking.form);
  const total = totalPrice(booking.seats);

  function updateField<K extends keyof BookingFormValues>(field: K, value: BookingFormValues[K]) {
    setBooking({ ...booking!, form: { ...booking!.form, [field]: value } });
  }

  function markTouched(field: FieldName) {
    setTouched((prev) => ({ ...prev, [field]: true }));
  }

  async function handlePay() {
    const currentErrors = validateForm(booking!.form);
    if (Object.keys(currentErrors).length > 0) {
      setTouched(ALL_TOUCHED);
      showToast('The form contains errors');
      return;
    }
    setSubmitting(true);
    try {
      const seats = orderedSeatIds(booking!.seats);
      await createReservation({
        screeningId,
        seats,
        customer: {
          firstName: booking!.form.firstName,
          lastName: booking!.form.lastName,
          email: booking!.form.email,
          phone: booking!.form.phone,
        },
        totalPrice: total,
      });
      setBooking({ ...booking!, paid: true, paidEmail: booking!.form.email });
      navigate('/confirmation');
    } catch {
      showToast('Payment failed. Please try again.');
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <div>
      <h1 data-testid="checkout-title">Your details</h1>
      <form>
        {TEXT_FIELDS.map((field) => (
          <div key={field.name}>
            <label data-testid={field.labelTestid} htmlFor={field.name}>
              {field.label}
            </label>
            <TextField
              id={field.name}
              data-testid={field.testid}
              value={booking.form[field.name]}
              onChange={(e) => updateField(field.name, e.target.value)}
              onBlur={() => markTouched(field.name)}
            />
            {touched[field.name] && errors[field.name] && (
              <div data-testid={field.errorTestid}>{errors[field.name]}</div>
            )}
          </div>
        ))}
        <div>
          <FormControlLabel
            control={
              <Checkbox
                id="termsAccepted"
                data-testid="terms-checkbox"
                checked={booking.form.termsAccepted}
                onChange={(e) => {
                  updateField('termsAccepted', e.target.checked);
                  markTouched('termsAccepted');
                }}
              />
            }
            label={<span data-testid="terms-label">I accept the terms and conditions *</span>}
          />
          {touched.termsAccepted && errors.termsAccepted && <div data-testid="terms-error">{errors.termsAccepted}</div>}
        </div>
        <div>
          <Button data-testid="checkout-back-button" onClick={() => navigate(`/screenings/${screeningId}/summary`)}>
            Back
          </Button>
          <Button data-testid="pay-button" disabled={submitting} onClick={handlePay}>
            {submitting ? 'Processing…' : `Pay ${formatPrice(total)}`}
          </Button>
        </div>
      </form>
    </div>
  );
}

export default CheckoutPage;

import Button from '@mui/material/Button';
import { useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { clearBooking, getBookingSnapshot, useBooking } from '../lib/bookingStore';

export function ConfirmationPage() {
  const navigate = useNavigate();
  const booking = useBooking();

  useEffect(() => {
    const snapshot = getBookingSnapshot();
    if (!snapshot || !snapshot.paid) {
      navigate('/', { replace: true });
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  if (!booking || !booking.paid) {
    return null;
  }

  function handleContinue() {
    clearBooking();
    navigate('/');
  }

  return (
    <div>
      <h1 data-testid="confirmation-heading">Payment successful</h1>
      <div data-testid="confirmation-message">Your tickets will be sent shortly to {booking.paidEmail}</div>
      <Button data-testid="confirmation-continue-button" onClick={handleContinue}>
        Continue
      </Button>
    </div>
  );
}

export default ConfirmationPage;

import { Navigate, Route, Routes } from 'react-router-dom';
