  AISLE_1_COLUMN,
  AISLE_2_COLUMN,
  Cell,
  LEFT_LABEL_COLUMN,
  MAX_SEATS_PER_BOOKING,
  RIGHT_LABEL_COLUMN,
  ROW_COUNT,
  SEAT_COLORS,
  SeatState,
  blockColumns,
  couchState,
  gridColumn,
  seatId,
  seatState,
  toCells,
} from '../lib/seatLayout';
