17	  { name: 'firstName', label: 'First name *', testid: 'first-name-input', labelTestid: 'first-name-label', errorTestid: 'first-name-error' },
18	  { name: 'lastName', label: 'Last name *', testid: 'last-name-input', labelTestid: 'last-name-label', errorTestid: 'last-name-error' },
