1	import Button from '@mui/material/Button';
2	import { useEffect } from 'react';
3	import { useNavigate } from 'react-router-dom';
4	import { clearBooking, getBookingSnapshot, useBooking } from '../lib/bookingStore';
5	
6	export function ConfirmationPage() {
7	  const navigate = useNavigate();
8	  const booking = useBooking();
9	
10	  useEffect(() => {
11	    const snapshot = getBookingSnapshot();
12	    if (!snapshot || !snapshot.paid) {
13	      navigate('/', { replace: true });
14	    }
15	    // eslint-disable-next-line react-hooks/exhaustive-deps
16	  }, []);
17	
18	  if (!booking || !booking.paid) {
19	    return null;
20	  }
21	
22	  function handleContinue() {
23	    clearBooking();
24	    navigate('/');
25	  }
26	
27	  return (
28	    <div>
29	      <h1 data-testid="confirmation-heading">Payment successful</h1>
30	      <div data-testid="confirmation-message">Your tickets will be sent shortly to {booking.paidEmail}</div>
31	      <Button data-testid="confirmation-continue-button" onClick={handleContinue}>
32	        Continue
33	      </Button>
34	    </div>
35	  );
36	}
37	
38	export default ConfirmationPage;
39

